import os,re
root='.'
pat=re.compile(r'DeleteMemo|delete.*memo|memo.*delete|DELETE FROM|ON DELETE CASCADE',re.I)
for dp,dn,fs in os.walk(root):
    if any(x in dp.split(os.sep) for x in ['.git','node_modules']): continue
    for f in fs:
        if not f.endswith(('.go','.sql','.ts','.tsx','.js','.py','.rs','.java')): continue
        p=os.path.join(dp,f)
        try: lines=open(p,errors='ignore').read().splitlines()
        except: continue
        for i,l in enumerate(lines):
            if pat.search(l):
                print(f'{p}:{i+1}: {l}')
PY

